using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;

class EditorPlacedObject:MonoBehaviour {internal string id,source;internal Mesh mesh;internal Material[] materials;internal Matrix4x4 origin;internal int firstSubMesh;void LateUpdate(){if(mesh==null)return;for(int i=0;i<materials.Length&&firstSubMesh+i<mesh.subMeshCount;i++)if(materials[i]!=null)Graphics.DrawMesh(mesh,transform.localToWorldMatrix*origin,materials[i],gameObject.layer,null,firstSubMesh+i);}}
partial class ModEditorWindow {
 string editScene="",sceneSearch="";bool chooseScene,sceneLoading;Scene ownedScene;Vector2 sceneScroll;Rect sceneRect;
 List<Transform> props=new List<Transform>();int libraryPage;
 void FlyCamera(){if(!Open||viewCamera==null||!Input.GetMouseButton(1)||!sceneRect.Contains(new Vector2(Input.mousePosition.x,Screen.height-Input.mousePosition.y)))return;var motion=new Vector3((Input.GetKey(KeyCode.D)?1:0)-(Input.GetKey(KeyCode.A)?1:0),(Input.GetKey(KeyCode.E)?1:0)-(Input.GetKey(KeyCode.Q)?1:0),(Input.GetKey(KeyCode.W)?1:0)-(Input.GetKey(KeyCode.S)?1:0));viewCamera.transform.position+=viewCamera.transform.TransformDirection(motion.normalized)*Time.unscaledDeltaTime*(Input.GetKey(KeyCode.LeftShift)?18:5);}
 void DrawSceneChooser(){if(GUILayout.Button(sceneLoading?"Загрузка…":"Сцена: "+(editScene.Length==0?"выбрать":editScene)))chooseScene=!chooseScene;if(!chooseScene)return;sceneSearch=GUILayout.TextField(sceneSearch);sceneScroll=GUILayout.BeginScrollView(sceneScroll,GUILayout.Height(150));for(int i=0;i<SceneManager.sceneCountInBuildSettings;i++){string path=SceneUtility.GetScenePathByBuildIndex(i),name=System.IO.Path.GetFileNameWithoutExtension(path);if(name.IndexOf(sceneSearch,StringComparison.OrdinalIgnoreCase)<0)continue;if(GUILayout.Button(name)&&!sceneLoading){chooseScene=false;StartCoroutine(OpenEditorScene(name));}}GUILayout.EndScrollView();}
 internal IEnumerator OpenEditorScene(string name){
  if(sceneLoading||(editScene==name&&SceneManager.GetSceneByName(name).isLoaded))yield break;sceneLoading=true;CancelTransformDrag();selected=null;props.Clear();ReleaseEditorScene();
  var scene=SceneManager.GetSceneByName(name);
  if(!scene.IsValid()||!scene.isLoaded){
   var maps=LightmapSettings.lightmaps;var sky=RenderSettings.skybox;var ambient=RenderSettings.ambientLight;var mode=RenderSettings.ambientMode;float intensity=RenderSettings.ambientIntensity;bool fog=RenderSettings.fog;
   UnityEngine.Events.UnityAction<Scene,LoadSceneMode> prepare=(loaded,loadMode)=>{if(loaded.name!=name)return;ownedScene=loaded;foreach(var root in loaded.GetRootGameObjects()){bool active=root.activeSelf;root.SetActive(false);foreach(var b in root.GetComponentsInChildren<Behaviour>(true))if(!(b is Light))b.enabled=false;foreach(var body in root.GetComponentsInChildren<Rigidbody>(true))body.isKinematic=true;foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;root.SetActive(active);}};
   SceneManager.sceneLoaded+=prepare;AsyncOperation operation=null;try{operation=SceneManager.LoadSceneAsync(name,LoadSceneMode.Additive);}catch(Exception ex){ModEditorStore.Status=ex.Message;}if(operation!=null)yield return operation;SceneManager.sceneLoaded-=prepare;
   LightmapSettings.lightmaps=maps;RenderSettings.skybox=sky;RenderSettings.ambientLight=ambient;RenderSettings.ambientMode=mode;RenderSettings.ambientIntensity=intensity;RenderSettings.fog=fog;scene=SceneManager.GetSceneByName(name);
  }
  if(scene.IsValid()&&scene.isLoaded){editScene=name;RefreshRoots();RefreshProps();if(viewCamera!=null){viewCamera.cullingMask=ownedScene.IsValid()?1<<31:-1;var available=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Renderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();var anchor=available.FirstOrDefault(r=>r.name=="BossChair")??available.FirstOrDefault(r=>r is MeshRenderer);if(anchor!=null){Select(anchor.transform);Frame();}}ModEditorStore.Apply();ModEditorStore.Status="Сцена открыта для редактирования: "+name;FloorAdmin.Log("EDITOR scene ready "+name+" props="+props.Count);}
  sceneLoading=false;
 }
 void ReleaseEditorScene(){if(ownedScene.IsValid()&&ownedScene.isLoaded){var old=ownedScene;foreach(var root in old.GetRootGameObjects())root.SetActive(false);SceneManager.UnloadSceneAsync(old);}ownedScene=default(Scene);editScene="";props.Clear();if(viewCamera!=null)viewCamera.cullingMask=-1;}
 void RefreshProps(){props=Resources.FindObjectsOfTypeAll<MeshFilter>().Where(m=>m.sharedMesh!=null&&m.gameObject.scene.IsValid()&&m.gameObject.scene.isLoaded&&(editScene.Length==0||m.gameObject.scene.name==editScene)&&m.GetComponent<MeshRenderer>()!=null&&m.GetComponentInParent<EditorPlacedObject>()==null).Select(m=>m.transform).OrderBy(t=>t.name).ToList();libraryPage=0;}
 void DrawPropLibrary(Rect rect){if(fullCatalog){DrawCatalog(rect);return;}GUILayout.BeginArea(rect,GUI.skin.box);GUILayout.BeginHorizontal();GUILayout.Label("Предметы сцены",heading);if(GUILayout.Button("Все файлы"))fullCatalog=true;assetSearch=GUILayout.TextField(assetSearch,GUILayout.Width(150));if(GUILayout.Button("Обновить"))RefreshProps();GUILayout.EndHorizontal();GUILayout.Label("ПКМ + WASD — полёт; Q/E — вниз/вверх; Shift — быстрее. Предметы размещаются как декорации.",small);var matches=props.Where(t=>t!=null&&(assetSearch.Length==0||t.name.IndexOf(assetSearch,StringComparison.OrdinalIgnoreCase)>=0)).ToArray();libraryPage=Mathf.Clamp(libraryPage,0,Mathf.Max(0,(matches.Length-1)/40));assetScroll=GUILayout.BeginScrollView(assetScroll);foreach(var item in matches.Skip(libraryPage*40).Take(40)){GUILayout.BeginHorizontal();GUILayout.Label(item.name,small);if(GUILayout.Button("Поставить",GUILayout.Width(90)))Try(()=>PlaceProp(item));GUILayout.EndHorizontal();}GUILayout.EndScrollView();GUILayout.BeginHorizontal();if(GUILayout.Button("←"))libraryPage=Mathf.Max(0,libraryPage-1);GUILayout.Label((libraryPage+1)+" / "+Mathf.Max(1,(matches.Length+39)/40)+" · "+matches.Length+" предметов");if(GUILayout.Button("→"))libraryPage++;GUILayout.EndHorizontal();GUILayout.EndArea();}
 internal void PlaceProp(Transform source){if(viewCamera==null)throw new Exception("Нет камеры сцены");var point=viewCamera.transform.position+viewCamera.transform.forward*4;RaycastHit hit;if(Physics.Raycast(viewCamera.ViewportPointToRay(new Vector3(.5f,.5f)),out hit,30,viewCamera.cullingMask))point=hit.point+hit.normal*.05f;var change=new EditorChange{kind="spawn",scene=source.gameObject.scene.name,path="$spawn/"+Guid.NewGuid().ToString("N"),source=ModEditorStore.Key(source),x=point.x,y=point.y,z=point.z,rx=source.eulerAngles.x,ry=source.eulerAngles.y,rz=source.eulerAngles.z,sx=source.lossyScale.x,sy=source.lossyScale.y,sz=source.lossyScale.z};ModEditorStore.Change(change);var placed=ModEditorStore.FindSpawn(change.path);if(placed!=null)Select(placed.transform);RefreshRoots();}
 internal IEnumerator VerifyLibrary(bool read){Show();yield return OpenEditorScene("BossRoom");if(read){ModEditorStore.Apply();var patch=ModEditorStore.Project.changes.First(p=>p.kind=="spawn");if(ModEditorStore.FindSpawn(patch.path)==null)throw new Exception("Placed object missing after restart");FloorAdmin.Log("PASS placed object restored after restart");ModEditorStore.New("MyMod");ModEditorStore.Save();}else{ModEditorStore.New("__library_verification");PlaceProp(props.First(p=>p.name=="BossChair"));var patch=ModEditorStore.Project.changes.Single();if(ModEditorStore.FindSpawn(patch.path)==null)throw new Exception("Placement failed");ModEditorStore.Undo();if(ModEditorStore.FindSpawn(patch.path)!=null)throw new Exception("Placement undo failed");ModEditorStore.Redo();if(ModEditorStore.FindSpawn(patch.path)==null)throw new Exception("Placement redo failed");ModEditorStore.Save();Select(ModEditorStore.FindSpawn(patch.path).transform);Frame();FloorAdmin.Log("PASS scene from menu, place prop, undo/redo, save");}}
}






